--[[ NIGHTDLC packed ]]
local function _ndlc_load(src)
	local L = loadstring or load
	if type(L) ~= "function" then warn("[NIGHTDLC] no loadstring") return end
	local fn, err = L(src)
	if not fn then warn("[NIGHTDLC] unpack: "..tostring(err)) return end
	local ok, e = pcall(fn)
	if not ok then warn("[NIGHTDLC] runtime: "..tostring(e)) end
end
do
	local name = "Unknown"
	pcall(function()
		if type(identifyexecutor)=="function" then name=tostring(identifyexecutor() or name)
		elseif type(getexecutorname)=="function" then name=tostring(getexecutorname() or name) end
	end)
	if type(getgenv)=="function" then getgenv().NIGHTDLC_EXECUTOR=name end
	print("[NIGHTDLC] packed · "..name)
end
local function _ndlc_decode(payload, key)
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	payload = tostring(payload or ""):gsub("[^"..alphabet.."=]", "")
	local data, build = {}, {}
	local function push(n)
		table.insert(build, string.char(n))
		if #build >= 4096 then table.insert(data, table.concat(build)); build = {} end
	end
	for i = 1, #payload, 4 do
		local a=(alphabet:find(payload:sub(i,i),1,true) or 1)-1
		local b=(alphabet:find(payload:sub(i+1,i+1),1,true) or 1)-1
		local c=(alphabet:find(payload:sub(i+2,i+2),1,true) or 1)-1
		local d=(alphabet:find(payload:sub(i+3,i+3),1,true) or 1)-1
		local n=a*262144+b*4096+c*64+d
		push(math.floor(n/65536)%256)
		if payload:sub(i+2,i+2)~="=" then push(math.floor(n/256)%256) end
		if payload:sub(i+3,i+3)~="=" then push(n%256) end
	end
	if #build>0 then table.insert(data, table.concat(build)) end
	local raw = table.concat(data)
	local out, chunk = {}, {}
	local klen = #key
	for i=1,#raw do
		local byte, kb = string.byte(raw,i), key[((i-1)%klen)+1]
		local x,y,r,p2 = byte,kb,0,1
		while x>0 or y>0 do
			local xb,yb=x%2,y%2
			if xb~=yb then r=r+p2 end
			x,y,p2=(x-xb)/2,(y-yb)/2,p2*2
		end
		table.insert(chunk, string.char(r))
		if #chunk>=4096 then table.insert(out, table.concat(chunk)); chunk={} end
	end
	if #chunk>0 then table.insert(out, table.concat(chunk)) end
	return table.concat(out)
end
local _KEY = {137,77,130,13,188,69,252,150,154,249,16,144,176,249,103,62,235,159,187,252,244,70,187,151,246,58,1,133,113,116,242,134}
local _PAYLOAD = [==[]==]
local ok, src = pcall(_ndlc_decode, _PAYLOAD, _KEY)
if not ok or type(src)~="string" or #src<100 then warn("[NIGHTDLC] decode failed") return end
_ndlc_load(src)
